@private  
@returns {Array} details The details to modify.  
@param {number} bitmask The bitmask flags; see `createWrap` for details.  
@returns {Array} The modified details.

@example  // Each day from 6 October 2014 through 10 October 2014:
var result = eachDayOfInterval({
  start: new Date(2014, 9, 6),
  end: new Date(2014, 9, 10)
})
//=> [
//   Mon Oct 06 2014 00:00:00,
//   Tue Oct 07 2014 00:00:00,
//   Wed Oct 08 2014 00:00:00,
//   Thu Oct 09 2014 00:00:00,
//   Fri Oct 10 2014 00:00:00
// ]

@example

// Each day from 6 October 2014 through 10 October 2014:
var result = eachDayOfInterval({
  start: new Date(2014, 9, 6),
  end: new Date(2014, 9, 10)
})
//=> [
//   Mon Oct 06 2014 00:00:00,
//   Tue Oct 07 2014 00:00:00,
//   Wed Oct 08 2014 00:00:00,
//   Thu Oct 09 2014 00:00:00,
//   Fri Oct 10 2014 00:00:00
// ]

@example

// Each quarter within the interval 6 February 2014–10 August 2014:
var result = eachQuarterOfInterval({
  start: new Date(2014, 1, 6),
  end: new Date(2014, 7, 10)
})
//=> [
//   Wed Jan 01 2014 00:00:00,
//   Tue Apr 01 2014 00:00:00,
//   Tue Jul 01 2014 00:00:00,
// ]

@example  // Each quarter in the interval 6 February 2014–10 August 2014:
var result = eachQuarterOfInterval({
  start: new Date(2014, 1, 6),
  end: new Date(2014, 7, 10)
})
//=> [
  //   Wed Jan 01 2014 00:00:00,
  //   Tue Apr 01 2014 00:00:00,
  //   Tue Jul 01 2014 00:00:00,
  // ]

